### java
```java
import java.util.*;

class DSU {
    private int[] p, siz;

    // 构造函数
    public DSU(int n) {
        p = new int[n + 1];
        siz = new int[n + 1];
        Arrays.fill(siz, 1);
        for (int i = 0; i <= n; i++) {
            p[i] = i;
        }
    }

    // 查找函数（带路径压缩）
    public int find(int x) {
        if (p[x] == x) {
            return x;
        } else {
            p[x] = find(p[x]);
            return p[x];
        }
    }

    // 判断两个节点是否在同一个集合
    public boolean same(int x, int y) {
        return find(x) == find(y);
    }

    // 合并两个集合
    public boolean merge(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return false;
        siz[x] += siz[y];
        p[y] = x;
        return true;
    }

    // 获取集合的大小
    public int size(int x) {
        return siz[find(x)];
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        Set<Integer> st = new HashSet<>();
        Set<String> g = new HashSet<>();
        DSU dsu = new DSU(n);

        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();

            if (u == v) continue; // 忽略自环边

            String edge = u < v ? u + "," + v : v + "," + u;
            if (g.contains(edge)) {
                System.out.println("No");
                continue;
            }

            if (!dsu.same(u, v)) {
                dsu.merge(u, v);
                System.out.println("No");
            } else {
                int fa = dsu.find(u);
                if (st.contains(fa)) {
                    System.out.println("No");
                } else {
                    System.out.println("Yes");
                    dsu.merge(u, v);
                    st.add(fa);
                }
            }
            g.add(edge);
        }
        scanner.close();
    }
}
